import{getService}from"azure-devops-extension-sdk";export class PeoplePickerProvider{constructor(){this.addIdentitiesToMRU=(e=>this.identityService.then(t=>t.addMruIdentitiesAsync(e))),this.getEntityFromUniqueAttribute=(e=>this.identityService.then(t=>t.searchIdentitiesAsync(e,["user"],["ims","source"],"uid").then(e=>e[0]))),this.onEmptyInputFocus=(()=>this.identityService.then(e=>e.getIdentityMruAsync().then(e=>e))),this.onFilterIdentities=((e,t)=>this._onSearchPersona(e,t||[])),this.onRequestConnectionInformation=((e,t)=>this.identityService.then(i=>i.getConnections(e,t))),this.removeIdentitiesFromMRU=(e=>this.identityService.then(t=>t.removeMruIdentitiesAsync(e))),this._onSearchPersona=((e,t)=>{const i={query:e};return this.identityService.then(e=>e.searchIdentitiesAsync(i.query,i.identityTypes,i.operationScopes,i.queryTypeHint,i.options).then(e=>e.filter(e=>!t.some(t=>t.entityId===e.entityId))))}),this.identityService=getService("ms.vss-features.identity-service")}};